+/// A number written in place: `255`, `0x2B`, `1.0`, `0.5_f32`.
+fn is_number(arg: &str) -> bool {
+    let a = arg.trim();
+    a.starts_with(|c: char| c.is_ascii_digit())
+        && a.chars()
+            .all(|c| c.is_ascii_alphanumeric() || c == '_' || c == '.')
